import{_ as o,o as s,c as d,a2 as t}from"./chunks/framework.ei62kzQy.js";const u=JSON.parse('{"title":"Design tokens","description":"","frontmatter":{},"headers":[],"relativePath":"design/README.md","filePath":"design/README.md"}'),a={name:"design/README.md"};function i(n,e,c,l,p,r){return s(),d("div",null,[...e[0]||(e[0]=[t(`<h1 id="design-tokens" tabindex="-1">Design tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design tokens&quot;">​</a></h1><p><code>tokens.json</code> is the single source for Coach Poulpy&#39;s colours, mood shades, type scale, spacing, radius and motion. Edit it, then regenerate the platform files:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>app-android/.../ui/PoulpyTokens.kt</code></td><td><code>CoachPoulpyTheme</code> (Material 3 colour scheme, typography, shapes) plus <code>PoulpyPalette</code>, <code>PoulpyMood</code>, <code>PoulpySpace</code>, <code>PoulpyRadius</code>, <code>PoulpyMotion</code></td></tr><tr><td><code>app-ios/CoachPoulpy/Theme/PoulpyTokens.swift</code></td><td><code>PoulpyColor</code> (light and dark), <code>PoulpyPalette</code>, <code>PoulpyMood</code>, <code>PoulpyFont</code>, <code>PoulpySpace</code>, <code>PoulpyRadius</code>, <code>PoulpyMotion</code></td></tr><tr><td><code>app-ios/.../AccentColor.colorset/Contents.json</code></td><td>The iOS accent colour (buttons, links, toggles)</td></tr><tr><td><code>web/src/styles/tokens.css</code></td><td>CSS custom properties (<code>--cp-*</code>), with dark values under <code>prefers-color-scheme</code></td></tr></tbody></table><p>CI runs <code>node design/build-tokens.mjs --check</code> and fails if a generated file no longer matches <code>tokens.json</code>.</p><p>Colour rules:</p><ul><li>The <code>poulpy</code> colours (blue, ember, ink) are the mascot&#39;s fabric and are the same in light and dark.</li><li>The blue side (<code>mood.proud</code>, <code>mood.happy</code>, <code>mood.recovering</code>) means the plan is on track; the ember side (<code>mood.annoyed</code>, <code>mood.grumpy</code>, <code>mood.fuming</code>) means a session slipped.</li><li>The plush blue and ember are too light for white text: buttons use <code>primary</code> (lagoon 600) and <code>grumpy</code> (ember 600).</li><li><code>error</code> is a crimson, always shown with an icon and text, so it is never confused with a grumpy Poulpy.</li></ul><p>The brand fonts are Baloo 2 (headings) and Nunito (body). The website loads them from Google Fonts. The apps bundle one static file per weight listed under <code>font</code> in <code>tokens.json</code>, in <code>app-android/src/main/res/font</code> and <code>app-ios/CoachPoulpy/Fonts</code>. After changing those weights, rebuild the files and the theme:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fonttools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/fonts/build-fonts.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span></span></code></pre></div><p>On iOS, also list any new file under <code>UIAppFonts</code> in <code>Info.plist</code>. Views use <code>.font(.poulpy(.headline))</code> instead of <code>.font(.headline)</code> to get the system text styles in the brand fonts. Both fonts are under the SIL Open Font License (<code>design/fonts/OFL-*.txt</code>).</p><h2 id="poulpy-s-drawings" tabindex="-1">Poulpy&#39;s drawings <a class="header-anchor" href="#poulpy-s-drawings" aria-label="Permalink to &quot;Poulpy&#39;s drawings&quot;">​</a></h2><p><code>build-poulpy.mjs</code> draws Poulpy&#39;s six mood portraits and twelve poses with the brand book&#39;s own drawing code, plus the loading animation&#39;s top view and the app icon, and writes them for each platform:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy.mjs</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Generated file</th><th>Used by</th></tr></thead><tbody><tr><td><code>design/poulpy/*.svg</code></td><td>Reference copies, to look at or reuse on the web</td></tr><tr><td><code>app-android/src/main/res/drawable/poulpy_*.xml</code></td><td>Android vector drawables (<code>R.drawable.poulpy_pose_champion</code>)</td></tr><tr><td><code>app-ios/CoachPoulpy/Assets.xcassets/Poulpy/*.imageset</code></td><td>iOS vector assets (<code>Image(&quot;PoulpyPoseChampion&quot;)</code>)</td></tr><tr><td><code>app-android/src/main/res/drawable/ic_launcher_*.xml</code>, <code>mipmap-anydpi-v26/ic_launcher.xml</code></td><td>The Android launcher icon: an adaptive icon with a themed (monochrome) layer</td></tr><tr><td><code>app-ios/CoachPoulpy/Assets.xcassets/AppIcon.appiconset</code></td><td>The iOS app icon: 1024 px PNGs for light, dark and tinted</td></tr></tbody></table><p>Portraits and poses share one 248 × 226 frame, so they can replace each other without moving. The loader (<code>loader</code>, and <code>loader_small</code> with a thicker line for sizes under 32) is Poulpy seen from above as a blue outline of eight round lobes with short tails; <code>PoulpyLoader</code> on Android and iOS turns it clockwise once every 2.4 s (10 s when animations are reduced) and replaces the old Spinning pose. CI runs it with <code>--check</code> too. The shared <code>PoulpyDrawing</code> enum names each drawing, and <code>PoulpyCoach</code> picks which one Today shows.</p><p>The app icon is the brand book&#39;s: the happy blue Poulpy on Foam (<code>neutral.50</code>), and on Deep sea (<code>theme.dark.background</code>) for the iOS dark icon. On Android, Poulpy is scaled so his farthest arm sits on the 66 dp circle every launcher mask keeps; the themed icon is his silhouette at half strength with the eyes and smile at full. iOS only takes PNGs, so the script rasterises the icon itself, in plain JavaScript so every machine gets the same pixels; <code>--check</code> compares those pixels, not the compressed bytes.</p><p>The rules for using Poulpy are in <a href="./../docs/brand"><code>docs/brand.md</code></a>; the full brand book is in <code>site/public/brand/book.html</code> and on the docs site, and the decisions behind it are in <a href="./../docs/brand-decisions"><code>docs/brand-decisions.md</code></a>.</p>`,17)])])}const m=o(a,[["render",i]]);export{u as __pageData,m as default};
